"use strict";(globalThis.webpackChunkopenim_docs=globalThis.webpackChunkopenim_docs||[]).push([[7432],{49371(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>h,frontMatter:()=>a,metadata:()=>r,toc:()=>c});const r=JSON.parse('{"id":"golang/architectural/6","title":"Incremental Version Sync","description":"In an IM system, real-time message delivery is only one part of the user experience. Users also care about whether the conversation list is up to date, whether friend relationships remain consistent, whether group member changes are synchronized reliably, and whether data can recover quickly after logging in on multiple devices.","source":"@site/i18n/en/docusaurus-plugin-content-docs-blog/current/golang/architectural/6.md","sourceDirName":"golang/architectural","slug":"/golang/architectural/6","permalink":"/blog/golang/architectural/6","draft":false,"unlisted":false,"editUrl":"https://github.com/OpenIMSDK/docs/tree/main/docs/blog/golang/architectural/6.md","tags":[],"version":"current","lastUpdatedAt":1781517623000,"sidebarPosition":6,"frontMatter":{"title":"Incremental Version Sync","hide_title":true,"sidebar_position":6},"sidebar":"tutorialSidebar","previous":{"title":"How OpenIM Ensures Client-Server Data Consistency in 100,000-Member Groups","permalink":"/blog/golang/architectural/5"},"next":{"title":"Write Diffusion Sync","permalink":"/blog/golang/architectural/7"}}');var i=t(86070),s=t(81753);const a={title:"Incremental Version Sync",hide_title:!0,sidebar_position:6},o="Incremental Version Sync Capability",l={},c=[{value:"Sync Built for Large-Scale IM Data",id:"sync-built-for-large-scale-im-data",level:2},{value:"Server and SDK Work Together",id:"server-and-sdk-work-together",level:2},{value:"Sync Changes Only, Avoid Repeated Data Transfer",id:"sync-changes-only-avoid-repeated-data-transfer",level:2},{value:"Faster Login and Cold Start",id:"faster-login-and-cold-start",level:2},{value:"More Reliable Recovery in Weak Networks and Offline Scenarios",id:"more-reliable-recovery-in-weak-networks-and-offline-scenarios",level:2},{value:"Consistent Data Across Multiple Devices",id:"consistent-data-across-multiple-devices",level:2},{value:"Detect Abnormal States and Self-Heal",id:"detect-abnormal-states-and-self-heal",level:2},{value:"Fill Missing Details on Demand",id:"fill-missing-details-on-demand",level:2},{value:"More Predictable Server Load",id:"more-predictable-server-load",level:2},{value:"Better for Long-Term Enterprise IM Evolution",id:"better-for-long-term-enterprise-im-evolution",level:2},{value:"Product Value Summary",id:"product-value-summary",level:2}];function d(e){const n={h1:"h1",h2:"h2",header:"header",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"incremental-version-sync-capability",children:"Incremental Version Sync Capability"})}),"\n",(0,i.jsx)(n.p,{children:"In an IM system, real-time message delivery is only one part of the user experience. Users also care about whether the conversation list is up to date, whether friend relationships remain consistent, whether group member changes are synchronized reliably, and whether data can recover quickly after logging in on multiple devices."}),"\n",(0,i.jsx)(n.p,{children:"As an organization grows, the amount of friend, group, conversation, and group member data keeps increasing. If the client has to pull all data again after every login, device switch, or network recovery, startup becomes slower, mobile data and battery usage increase, and the server has to process a large number of repeated requests."}),"\n",(0,i.jsx)(n.p,{children:"The server and SDK provide an incremental version sync mechanism. Its goal is straightforward: the client should synchronize only the data that actually changed, while still maintaining eventual consistency in weak network, offline, multi-device, and abnormal local data scenarios."}),"\n",(0,i.jsx)(n.h2,{id:"sync-built-for-large-scale-im-data",children:"Sync Built for Large-Scale IM Data"}),"\n",(0,i.jsx)(n.p,{children:"Incremental version sync applies to the most common list-style data in IM systems:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Conversation lists"}),"\n",(0,i.jsx)(n.li,{children:"Friend lists"}),"\n",(0,i.jsx)(n.li,{children:"Joined group lists"}),"\n",(0,i.jsx)(n.li,{children:"Group member lists"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"These data sets share one important pattern: the total amount of data can be large, but the amount of data changed in a single update is usually very small. Examples include adding a friend, changing a group member role, updating a group member nickname, or updating conversation information. Traditional full sync would pull the entire list again, while incremental version sync focuses only on the actual change."}),"\n",(0,i.jsx)(n.p,{children:"For users, this means faster login, more timely list updates, and smoother recovery in weak network conditions. For the server, it means less redundant traffic, lower database pressure, and more predictable system load."}),"\n",(0,i.jsx)(n.h2,{id:"server-and-sdk-work-together",children:"Server and SDK Work Together"}),"\n",(0,i.jsx)(n.p,{children:"This capability is not implemented by the server or SDK alone. It depends on coordinated behavior on both sides."}),"\n",(0,i.jsx)(n.p,{children:"The server maintains authoritative data and version changes. When friend or group member data is inserted, updated, or deleted, or when conversation information is updated, the server advances the version of the corresponding data set and records the change. The SDK stores the last synchronized version state locally and updates the local database according to the changes returned by the server."}),"\n",(0,i.jsx)(n.p,{children:"This coordination makes it possible to:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Avoid repeatedly pulling data that already exists locally."}),"\n",(0,i.jsx)(n.li,{children:"Let the server accurately determine whether the client is behind."}),"\n",(0,i.jsx)(n.li,{children:"Allow the client to recover missing changes through version differences after online notifications are lost."}),"\n",(0,i.jsx)(n.li,{children:"Automatically fall back to a full correction flow when local data is abnormal."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:'In simple terms, the server knows "what is current", and the SDK knows "where the local client stopped". By aligning through version state, both sides can catch up efficiently.'}),"\n",(0,i.jsx)(n.h2,{id:"sync-changes-only-avoid-repeated-data-transfer",children:"Sync Changes Only, Avoid Repeated Data Transfer"}),"\n",(0,i.jsx)(n.p,{children:"The biggest product value of incremental version sync is reducing repeated data transfer."}),"\n",(0,i.jsx)(n.p,{children:"When a user has many groups and conversations, the actual change may involve only one or two items. The client does not need to download the entire list again for such a small change. Instead, it merges local data based on inserted and updated content; for data types that support deletion semantics, delete results can also be synchronized."}),"\n",(0,i.jsx)(n.p,{children:"For example:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"When a friend is added, only the new friend information is synchronized."}),"\n",(0,i.jsx)(n.li,{children:"When friend information changes, only the changed friend item is synchronized."}),"\n",(0,i.jsx)(n.li,{children:"When conversation information changes, only the changed conversation item is synchronized."}),"\n",(0,i.jsx)(n.li,{children:"When a group member role or nickname changes, only the corresponding member change is synchronized."}),"\n",(0,i.jsx)(n.li,{children:"When group member ordering changes, only the necessary ordering information is refreshed."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"This is especially important for large organizations. The more users, groups, and members there are, the more obvious the benefit of incremental sync becomes."}),"\n",(0,i.jsx)(n.h2,{id:"faster-login-and-cold-start",children:"Faster Login and Cold Start"}),"\n",(0,i.jsx)(n.p,{children:"When an IM client starts, users expect to see conversations, friends, and groups as quickly as possible. Full sync can slow down startup because it requires downloading a large amount of data, especially on mobile networks, cross-region networks, or private deployment environments."}),"\n",(0,i.jsx)(n.p,{children:"Incremental version sync allows the SDK to display existing local data first, then check in the background whether the server has new changes. In most cases, the client only needs to pull a small number of changes to complete the refresh."}),"\n",(0,i.jsx)(n.p,{children:"This improves the experience in several ways:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The app opens faster."}),"\n",(0,i.jsx)(n.li,{children:"Lists appear faster."}),"\n",(0,i.jsx)(n.li,{children:"Data refresh feels smoother."}),"\n",(0,i.jsx)(n.li,{children:"Small changes do not block the full page from loading."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"From the user's perspective, the data appears quickly instead of making every startup feel like the first sync after a fresh installation."}),"\n",(0,i.jsx)(n.h2,{id:"more-reliable-recovery-in-weak-networks-and-offline-scenarios",children:"More Reliable Recovery in Weak Networks and Offline Scenarios"}),"\n",(0,i.jsx)(n.p,{children:"Mobile environments are naturally unstable. Users may switch the app to the background, lose network access, move between networks, or come back online after being offline for a long time. If synchronization depends only on online notifications, a lost or out-of-order notification can cause the client to miss changes."}),"\n",(0,i.jsx)(n.p,{children:"Incremental version sync does not treat notifications as the only source of truth. A notification is more like a trigger: it tells the SDK that a new version may need to be checked. The SDK compares the locally stored version state with the latest server version, then decides whether it can apply the change directly or needs to pull missing data again."}),"\n",(0,i.jsx)(n.p,{children:"This means:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Losing one notification does not cause permanent data inconsistency."}),"\n",(0,i.jsx)(n.li,{children:"A client that has been offline for a long time can continue catching up from its last version."}),"\n",(0,i.jsx)(n.li,{children:"If synchronization is interrupted by network jitter, the next attempt can still recover."}),"\n",(0,i.jsx)(n.li,{children:"The client does not blindly trust expired or out-of-order notifications."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"For enterprise IM, this is critical. Organization relationships, group member permissions, and conversation state should not rely on a single real-time notification for correctness."}),"\n",(0,i.jsx)(n.h2,{id:"consistent-data-across-multiple-devices",children:"Consistent Data Across Multiple Devices"}),"\n",(0,i.jsx)(n.p,{children:"Enterprise users often use mobile, desktop, and web clients at the same time. Different devices may come online at different times, use different networks, and have different local cache states."}),"\n",(0,i.jsx)(n.p,{children:"Incremental version sync gives each device an independent way to catch up with server state. One offline device does not affect another device. When a device comes back online, it does not need to synchronize everything from the beginning; it can continue from its locally stored version."}),"\n",(0,i.jsx)(n.p,{children:"This makes the multi-device experience more stable:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"After a friend is added on mobile, the desktop client can synchronize the change."}),"\n",(0,i.jsx)(n.li,{children:"After group member changes are handled on desktop, the mobile client can catch up."}),"\n",(0,i.jsx)(n.li,{children:"A device that has been offline for a long time can recover to the server's current state after login."}),"\n",(0,i.jsx)(n.li,{children:"Different devices do not remain inconsistent because of local cache differences."}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"detect-abnormal-states-and-self-heal",children:"Detect Abnormal States and Self-Heal"}),"\n",(0,i.jsx)(n.p,{children:"Incremental sync is not only a performance optimization. It is also a reliability mechanism."}),"\n",(0,i.jsx)(n.p,{children:"In real environments, the client may encounter local database corruption, cache cleanup, missing historical versions, or version chain changes. Server-side historical change logs may also be limited by capacity controls or cleanup policies."}),"\n",(0,i.jsx)(n.p,{children:"In these cases, the system does not force incomplete incremental changes onto the client. Instead, it automatically enters a full correction flow."}),"\n",(0,i.jsx)(n.p,{children:"Common scenarios include:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The client version is not continuous with the server version."}),"\n",(0,i.jsx)(n.li,{children:"The version identifier stored by the client does not match the server."}),"\n",(0,i.jsx)(n.li,{children:"Server-side historical change logs are not enough to fill the client's gap."}),"\n",(0,i.jsx)(n.li,{children:"The client has an ID locally but lacks the corresponding detail data."}),"\n",(0,i.jsx)(n.li,{children:"List ordering changes and needs to be corrected again."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"The value of this mechanism is clear: normal cases stay lightweight, and abnormal cases can repair themselves. It pursues efficiency while protecting the correctness baseline."}),"\n",(0,i.jsx)(n.h2,{id:"fill-missing-details-on-demand",children:"Fill Missing Details on Demand"}),"\n",(0,i.jsx)(n.p,{children:"The SDK stores the ID list of synchronized objects locally. This allows the client to paginate and display data according to local ordering first. If some detail records are missing, the SDK can fetch them from the server by ID."}),"\n",(0,i.jsx)(n.p,{children:"This approach is especially useful for long group member lists and friend lists. When users enter a page, the client does not need to download every detail record at once. It can fill missing items only when the user reaches that part of the list."}),"\n",(0,i.jsx)(n.p,{children:"The benefits are:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Faster first-screen loading."}),"\n",(0,i.jsx)(n.li,{children:"Lighter pagination for large lists."}),"\n",(0,i.jsx)(n.li,{children:"Better use of local cache."}),"\n",(0,i.jsx)(n.li,{children:"Network requests that better match the user's actual access path."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"For mobile and web clients, this feels more natural than pulling everything at once."}),"\n",(0,i.jsx)(n.h2,{id:"more-predictable-server-load",children:"More Predictable Server Load"}),"\n",(0,i.jsx)(n.p,{children:"From the server side, incremental version sync significantly reduces repeated reads and repeated data transfer."}),"\n",(0,i.jsx)(n.p,{children:"The server maintains the latest version state for each synchronized data set and records the necessary change logs. When the client requests synchronization, the server first checks whether the versions are already aligned. If they are aligned, there is no need to return a large data payload. If the client is behind, the server returns only the necessary changes. If complete incremental sync cannot be guaranteed, the server guides the client into full correction."}),"\n",(0,i.jsx)(n.p,{children:"This model helps the server control:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Database query pressure"}),"\n",(0,i.jsx)(n.li,{children:"Network egress traffic"}),"\n",(0,i.jsx)(n.li,{children:"Login-time sync pressure during traffic peaks"}),"\n",(0,i.jsx)(n.li,{children:"Sync cost for large groups and large organizations"}),"\n",(0,i.jsx)(n.li,{children:"Storage size of historical change logs"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"For private deployments, enterprise customers, and high-concurrency scenarios, this predictability has more long-term value than simply adding resources."}),"\n",(0,i.jsx)(n.h2,{id:"better-for-long-term-enterprise-im-evolution",children:"Better for Long-Term Enterprise IM Evolution"}),"\n",(0,i.jsx)(n.p,{children:"The server and SDK are independent code projects and can evolve independently. Incremental version sync forms a stable capability boundary between the two sides."}),"\n",(0,i.jsx)(n.p,{children:"The server can continue optimizing version logs, caches, cleanup strategies, and data query methods. The SDK can continue optimizing local databases, sync scheduling, on-demand detail filling, and UI refresh behavior. As long as the version sync semantics remain stable, both sides can improve independently."}),"\n",(0,i.jsx)(n.p,{children:"This matters for long-term product growth. As new business features are added, other list-style data can reuse a similar sync model instead of designing a new synchronization mechanism for every data type."}),"\n",(0,i.jsx)(n.h2,{id:"product-value-summary",children:"Product Value Summary"}),"\n",(0,i.jsx)(n.p,{children:"Incremental version sync solves a core IM system problem: data keeps growing, but synchronization must stay lightweight."}),"\n",(0,i.jsx)(n.p,{children:"Its core value includes:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Faster login and startup experience."}),"\n",(0,i.jsx)(n.li,{children:"Lower data and battery consumption."}),"\n",(0,i.jsx)(n.li,{children:"More stable recovery in weak network and offline scenarios."}),"\n",(0,i.jsx)(n.li,{children:"More reliable multi-device consistency."}),"\n",(0,i.jsx)(n.li,{children:"More predictable server resource usage."}),"\n",(0,i.jsx)(n.li,{children:"Better support for large groups and large organizations."}),"\n",(0,i.jsx)(n.li,{children:"Automatic correction in abnormal cases to avoid long-term inconsistency."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"For enterprise IM products, this is not just a technical optimization. It is a foundational capability that directly affects user experience, system stability, and scalability."}),"\n",(0,i.jsx)(n.p,{children:"By combining server-side version management with SDK-side local synchronization, the client synchronizes only changes in most cases and automatically performs full correction when necessary. This balances efficiency and reliability, and it is an important foundation for supporting multiple devices, weak networks, large-scale organization relationships, and complex group scenarios."})]})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},77462(e,n,t){var r=t(30758),i=Symbol.for("react.element"),s=Symbol.for("react.fragment"),a=Object.prototype.hasOwnProperty,o=r.__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED.ReactCurrentOwner,l={key:!0,ref:!0,__self:!0,__source:!0};function c(e,n,t){var r,s={},c=null,d=null;for(r in void 0!==t&&(c=""+t),void 0!==n.key&&(c=""+n.key),void 0!==n.ref&&(d=n.ref),n)a.call(n,r)&&!l.hasOwnProperty(r)&&(s[r]=n[r]);if(e&&e.defaultProps)for(r in n=e.defaultProps)void 0===s[r]&&(s[r]=n[r]);return{$$typeof:i,type:e,key:c,ref:d,props:s,_owner:o.current}}n.Fragment=s,n.jsx=c,n.jsxs=c},86070(e,n,t){e.exports=t(77462)},81753(e,n,t){t.d(n,{R:()=>a,x:()=>o});var r=t(30758);const i={},s=r.createContext(i);function a(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);